import {surfaces,rectShape,extent,posed} from './foam-model.js?v=20261023-desk8';
export class Foam3D{
 constructor(host){this.host=host;this.renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});this.renderer.setPixelRatio(Math.min(devicePixelRatio,2));this.renderer.setClearColor(0xf0f1eb,1);this.renderer.outputColorSpace=THREE.SRGBColorSpace;host.append(this.renderer.domElement);this.renderer.domElement.setAttribute('aria-label','3D foam preview. Drag to orbit, pinch to zoom.');this.renderer.domElement.setAttribute('role','img');this.scene=new THREE.Scene();this.camera=new THREE.PerspectiveCamera(38,1,.1,10000);this.camera.up.set(0,0,1);this.controls=new OrbitControls(this.camera,this.renderer.domElement);this.controls.enableDamping=false;this.controls.maxPolarAngle=Math.PI*.49;this.controls.minDistance=20;this.controls.addEventListener('change',()=>this.draw());this.scene.add(new THREE.HemisphereLight(0xffffff,0x61646a,2.4));const light=new THREE.DirectionalLight(0xffffff,3);light.position.set(-300,-400,800);this.scene.add(light);this.group=new THREE.Group();this.scene.add(this.group);this.ro=new ResizeObserver(()=>this.resize());this.ro.observe(host);this.revision=0;}
 material(color){return new THREE.MeshStandardMaterial({color,roughness:1,metalness:0,side:THREE.DoubleSide});}
 flat(shape,z,mat){for(const poly of shape){const s=new THREE.Shape(poly[0].map(([x,y])=>new THREE.Vector2(x,-y)));for(const r of poly.slice(1))s.holes.push(new THREE.Path(r.map(([x,y])=>new THREE.Vector2(x,-y))));const geom=new THREE.ShapeGeometry(s);if(mat===this.topMaterial){const positions=geom.getAttribute('position'),uv=geom.getAttribute('uv');for(let i=0;i<positions.count;i++)uv.setXY(i,positions.getX(i)/this.data.foam.width,1+positions.getY(i)/this.data.foam.height);}const mesh=new THREE.Mesh(geom,mat);mesh.position.z=z;this.group.add(mesh);}}
 wall(shape,top,bottom,mat){const v=[];for(const p of shape)for(const r of p)for(let i=1;i<r.length;i++){const [x,y]=r[i-1],[u,w]=r[i];v.push(x,-y,top,u,-w,top,u,-w,bottom,x,-y,top,u,-w,bottom,x,-y,bottom);}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(v,3));g.computeVertexNormals();this.group.add(new THREE.Mesh(g,mat));}
 update(data,selected=-1,photoURL=null){const reset=!this.data||this.data.foam.width!==data.foam.width||this.data.foam.height!==data.foam.height;this.data=data;while(this.group.children.length){const m=this.group.children.pop();m.geometry?.dispose();}for(const m of this.materials||[])m.dispose();const top=this.material('#424b4d'),side=this.material('#30393b'),floor=this.material('#b86c3f'),walls=this.material('#515b5d');this.topMaterial=top;if(photoURL!==this.photoURL){this.photoTexture?.dispose();this.photoTexture=null;this.photoURL=photoURL;if(photoURL){const url=photoURL;this.photoTexture=new THREE.TextureLoader().load(photoURL,()=>{if(this.photoURL===url)this.draw();});this.photoTexture.colorSpace=THREE.SRGBColorSpace;}}if(this.photoTexture){top.map=this.photoTexture;top.color.set('#ffffff');}this.materials=[top,side,floor,walls];const f=data.foam,s=surfaces(data.tools,f),board=rectShape(0,0,f.width,f.height);this.flat(s.top,f.thickness,top);this.flat(board,0,side);this.wall(board,f.thickness,0,side);for(const l of s.layers){this.flat(l.floor,f.thickness-l.depth,floor);this.wall(l.shape,f.thickness-l.from,f.thickness-l.depth,walls);}if(data.tools[selected]){const shape=posed(data.tools[selected]);const vertices=[];for(const p of shape)for(const r of p)for(let i=1;i<r.length;i++)vertices.push(r[i-1][0],-r[i-1][1],f.thickness+.25,r[i][0],-r[i][1],f.thickness+.25);const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));const m=new THREE.LineBasicMaterial({color:'#f4b574'});this.materials.push(m);this.group.add(new THREE.LineSegments(g,m));}this.host.dataset.revision=String(++this.revision);this.host.dataset.depths=s.layers.map(l=>l.depth).join(',');if(reset)this.reset();this.resize();}
 frameBox(box){const target=new THREE.Vector3((box.minX+box.maxX)/2,(box.minY+box.maxY)/2,(box.minZ+box.maxZ)/2),direction=new THREE.Vector3(.9,-1.05,1.45).normalize(),right=new THREE.Vector3().crossVectors(direction,new THREE.Vector3(0,0,1)).normalize(),up=new THREE.Vector3().crossVectors(right,direction).normalize(),tan=Math.tan(this.camera.fov*Math.PI/360),tanH=tan*this.camera.aspect;let distance=20;for(const x of [box.minX,box.maxX])for(const y of [box.minY,box.maxY])for(const z of [box.minZ,box.maxZ]){const p=new THREE.Vector3(x,y,z).sub(target),depth=p.dot(direction);distance=Math.max(distance,depth+Math.abs(p.dot(right))/tanH,depth+Math.abs(p.dot(up))/tan);}distance*=1.12;this.controls.target.copy(target);this.camera.position.copy(target).addScaledVector(direction,distance);this.camera.near=Math.max(.1,distance/2000);this.camera.far=distance*30;this.camera.updateProjectionMatrix();this.controls.update();this.draw();}
 focusTool(index){const t=this.data?.tools[index];if(!t)return;this.focusIndex=index;const b=extent(posed(t)),p=8;this.frameBox({minX:b.minX-p,maxX:b.maxX+p,minY:-b.maxY-p,maxY:-b.minY+p,minZ:this.data.foam.thickness-t.depth,maxZ:this.data.foam.thickness});}
 reset(){if(!this.data)return;this.focusIndex=null;const f=this.data.foam;this.controls.maxDistance=Math.max(f.width,f.height)*15;this.frameBox({minX:0,maxX:f.width,minY:-f.height,maxY:0,minZ:0,maxZ:f.thickness});}
 resize(){const w=this.host.clientWidth,h=this.host.clientHeight;if(w<1||h<1)return;const changed=Math.abs(this.camera.aspect-w/h)>.001;this.renderer.setSize(w,h,false);this.camera.aspect=w/h;this.camera.updateProjectionMatrix();if(changed&&this.data){if(this.focusIndex!==null&&this.focusIndex!==undefined)this.focusTool(this.focusIndex);else this.reset();}else this.draw();}
 draw(){if(this.host.clientWidth)this.renderer.render(this.scene,this.camera);}
}
